// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetWebAuthnRelatedOrigins passkey を使う origin の一覧（Related Origin Requests）
	// (GET /.well-known/webauthn)
	GetWebAuthnRelatedOrigins(w http.ResponseWriter, r *http.Request)
	// GetHealth ヘルスチェック
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// AcceptInvitation 招待を受け入れる（4.4）
	// (POST /v1/invitations:accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request)
	// StartEmailLogin メールのコード・マジックリンクによる登録・ログインを始める
	// (POST /v1/login/email:start)
	StartEmailLogin(w http.ResponseWriter, r *http.Request)
	// VerifyEmailLogin コードかマジックリンクのトークンでフローを完了する
	// (POST /v1/login/email:verify)
	VerifyEmailLogin(w http.ResponseWriter, r *http.Request)
	// RedeemLoginLink 運営者が発行したログイン用リンクでログインする
	// (POST /v1/login/link:redeem)
	RedeemLoginLink(w http.ResponseWriter, r *http.Request)
	// StartOAuthLogin 外部プロバイダ（OAuth / OIDC）による登録・ログインを始める
	// (POST /v1/login/oauth/{connection}:start)
	StartOAuthLogin(w http.ResponseWriter, r *http.Request, connection string)
	// CompleteOAuthLogin プロバイダからの戻り（state と code）でフローを完了する
	// (POST /v1/login/oauth:complete)
	CompleteOAuthLogin(w http.ResponseWriter, r *http.Request)
	// FinishPasskeyLogin passkey でのログインを完了する
	// (POST /v1/login/passkey:finish)
	FinishPasskeyLogin(w http.ResponseWriter, r *http.Request)
	// StartPasskeyLogin passkey でのログインを始める
	// (POST /v1/login/passkey:start)
	StartPasskeyLogin(w http.ResponseWriter, r *http.Request)
	// PasswordLogin メールとパスワードでログインする（フィーチャー password）
	// (POST /v1/login/password)
	PasswordLogin(w http.ResponseWriter, r *http.Request)
	// StartSecondFactorPasskey 2要素目の passkey の確認を始める
	// (POST /v1/login/second-factor/passkey:start)
	StartSecondFactorPasskey(w http.ResponseWriter, r *http.Request)
	// VerifySecondFactor 2要素目を確かめ、通常のセッションに替える
	// (POST /v1/login/second-factor:verify)
	VerifySecondFactor(w http.ResponseWriter, r *http.Request)
	// Logout 今のセッションを失効させる
	// (POST /v1/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// CancelMyAccountDeletion アカウントの削除の予定を取り消す
	// (POST /v1/me/account:cancel-deletion)
	CancelMyAccountDeletion(w http.ResponseWriter, r *http.Request)
	// DeleteMyAccount アカウントを削除する（4.10）
	// (POST /v1/me/account:delete)
	DeleteMyAccount(w http.ResponseWriter, r *http.Request)
	// MakeMyEmailPrimary 確認済みのメールを primary にする
	// (POST /v1/me/emails/{id}:make-primary)
	MakeMyEmailPrimary(w http.ResponseWriter, r *http.Request, id string)
	// RemoveMyEmail メールを消す
	// (POST /v1/me/emails/{id}:remove)
	RemoveMyEmail(w http.ResponseWriter, r *http.Request, id string)
	// StartAddEmail メールの追加を始める（所有確認のコードとリンクを通知する）
	// (POST /v1/me/emails:start)
	StartAddEmail(w http.ResponseWriter, r *http.Request)
	// VerifyAddEmail コードかリンクのトークンでメールの追加を完了する
	// (POST /v1/me/emails:verify)
	VerifyAddEmail(w http.ResponseWriter, r *http.Request)
	// StartLinkIdentity 外部プロバイダ（OAuth / OIDC）の連携を始める
	// (POST /v1/me/identities/{connection}:start)
	StartLinkIdentity(w http.ResponseWriter, r *http.Request, connection string)
	// UnlinkMyIdentity 外部 ID の連携を解除する
	// (POST /v1/me/identities/{id}:unlink)
	UnlinkMyIdentity(w http.ResponseWriter, r *http.Request, id string)
	// CompleteLinkIdentity プロバイダからの戻りで連携を完了する
	// (POST /v1/me/identities:complete)
	CompleteLinkIdentity(w http.ResponseWriter, r *http.Request)
	// ListMyMethods 本人の認証手段（メール、連携した外部 ID、passkey、TOTP、パスワード）の一覧
	// (GET /v1/me/methods)
	ListMyMethods(w http.ResponseWriter, r *http.Request)
	// ListMyOrgs 本人の Org の一覧（終了した Membership は含めない。11.13）
	// (GET /v1/me/orgs)
	ListMyOrgs(w http.ResponseWriter, r *http.Request)
	// CreateMyOrg 共有 Org を作り、本人を owner にする（4.11）
	// (POST /v1/me/orgs)
	CreateMyOrg(w http.ResponseWriter, r *http.Request)
	// ListOrgInvitations Org の招待の一覧（Org の owner と admin）
	// (GET /v1/me/orgs/{id}/invitations)
	ListOrgInvitations(w http.ResponseWriter, r *http.Request, id string)
	// InviteToOrg Org にアドレスを招待する（Org の owner と admin。owner として招待できるのは owner だけ。4.4）
	// (POST /v1/me/orgs/{id}/invitations)
	InviteToOrg(w http.ResponseWriter, r *http.Request, id string)
	// RevokeOrgInvitation pending の招待を取り消す（Org の owner と admin）
	// (POST /v1/me/orgs/{id}/invitations/{invitation_id}:revoke)
	RevokeOrgInvitation(w http.ResponseWriter, r *http.Request, id string, invitationId string)
	// ListOrgMembers Org のメンバーの一覧（Org の owner と admin。4.4）
	// (GET /v1/me/orgs/{id}/members)
	ListOrgMembers(w http.ResponseWriter, r *http.Request, id string, params ListOrgMembersParams)
	// UpdateOrgMember メンバーの有効期間を変更する（Org の owner と admin。4.8）
	// (PATCH /v1/me/orgs/{id}/members/{membership_id})
	UpdateOrgMember(w http.ResponseWriter, r *http.Request, id string, membershipId string)
	// ListOrgMemberSuspensions メンバーの停止の一覧（Org の owner と admin。customer_request だけ）
	// (GET /v1/me/orgs/{id}/members/{membership_id}/suspensions)
	ListOrgMemberSuspensions(w http.ResponseWriter, r *http.Request, id string, membershipId string)
	// SuspendOrgMember メンバーを停止する（Org の owner と admin。種別は customer_request。4.7）
	// (POST /v1/me/orgs/{id}/members/{membership_id}/suspensions)
	SuspendOrgMember(w http.ResponseWriter, r *http.Request, id string, membershipId string)
	// RemoveOrgMember メンバーを除名する（Org の owner と admin。4.10）
	// (POST /v1/me/orgs/{id}/members/{membership_id}:remove)
	RemoveOrgMember(w http.ResponseWriter, r *http.Request, id string, membershipId string)
	// GetMyOrgSettings Org の段のセキュリティ設定を返す（2.8）
	// (GET /v1/me/orgs/{id}/settings)
	GetMyOrgSettings(w http.ResponseWriter, r *http.Request, id string)
	// PutMyOrgSettings Org の段のセキュリティ設定を置き換える（2.8、5.4、10章）
	// (PUT /v1/me/orgs/{id}/settings)
	PutMyOrgSettings(w http.ResponseWriter, r *http.Request, id string)
	// LiftOrgSuspension メンバーの停止を解除する（Org の owner と admin。customer_request だけ）
	// (POST /v1/me/orgs/{id}/suspensions/{suspension_id}:lift)
	LiftOrgSuspension(w http.ResponseWriter, r *http.Request, id string, suspensionId string)
	// BindMyOrgEmail この Org で使うメールを結び付ける（4.4）
	// (POST /v1/me/orgs/{id}:bind-email)
	BindMyOrgEmail(w http.ResponseWriter, r *http.Request, id string)
	// CancelMyOrgDeletion Org の削除の予定を取り消す（Org の owner。猶予期間の間だけ）
	// (POST /v1/me/orgs/{id}:cancel-deletion)
	CancelMyOrgDeletion(w http.ResponseWriter, r *http.Request, id string)
	// DeleteMyOrg 共有 Org を削除する（Org の owner。4.10）
	// (POST /v1/me/orgs/{id}:delete)
	DeleteMyOrg(w http.ResponseWriter, r *http.Request, id string)
	// LeaveMyOrg 共有 Org から退会する（4.10）
	// (POST /v1/me/orgs/{id}:leave)
	LeaveMyOrg(w http.ResponseWriter, r *http.Request, id string)
	// SwitchMyOrg セッションの Org を切り替える（4.4）
	// (POST /v1/me/orgs/{id}:switch)
	SwitchMyOrg(w http.ResponseWriter, r *http.Request, id string)
	// TransferMyOrg オーナーを譲る（Org の owner。4.10）
	// (POST /v1/me/orgs/{id}:transfer)
	TransferMyOrg(w http.ResponseWriter, r *http.Request, id string)
	// RenameMyPasskey passkey の名前を変える
	// (POST /v1/me/passkeys/{id}:rename)
	RenameMyPasskey(w http.ResponseWriter, r *http.Request, id string)
	// RevokeMyPasskey passkey を無効化する
	// (POST /v1/me/passkeys/{id}:revoke)
	RevokeMyPasskey(w http.ResponseWriter, r *http.Request, id string)
	// SetMyPasskeyOrg この passkey でログインしたときに入る Org を決める（4.4）
	// (POST /v1/me/passkeys/{id}:set-org)
	SetMyPasskeyOrg(w http.ResponseWriter, r *http.Request, id string)
	// FinishRegisterPasskey passkey の登録を完了する
	// (POST /v1/me/passkeys:finish)
	FinishRegisterPasskey(w http.ResponseWriter, r *http.Request)
	// StartRegisterPasskey passkey の登録を始める
	// (POST /v1/me/passkeys:start)
	StartRegisterPasskey(w http.ResponseWriter, r *http.Request)
	// RemoveMyPassword パスワードを外す（フィーチャー password）
	// (POST /v1/me/password:remove)
	RemoveMyPassword(w http.ResponseWriter, r *http.Request)
	// SetMyPassword パスワードを設定・変更する（フィーチャー password）
	// (POST /v1/me/password:set)
	SetMyPassword(w http.ResponseWriter, r *http.Request)
	// RegenerateMyRecoveryCodes リカバリーコードを作り直す
	// (POST /v1/me/recovery-codes:regenerate)
	RegenerateMyRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// ListMySessions 本人の有効なセッションの一覧
	// (GET /v1/me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// RevokeMySession 本人のセッションを失効させる
	// (POST /v1/me/sessions/{id}:revoke)
	RevokeMySession(w http.ResponseWriter, r *http.Request, id string)
	// RevokeMyTOTP TOTP を無効化する
	// (POST /v1/me/totp/{id}:revoke)
	RevokeMyTOTP(w http.ResponseWriter, r *http.Request, id string)
	// ConfirmRegisterTOTP TOTP の登録をコードで完了する
	// (POST /v1/me/totp:confirm)
	ConfirmRegisterTOTP(w http.ResponseWriter, r *http.Request)
	// StartRegisterTOTP TOTP（認証器アプリ）の登録を始める
	// (POST /v1/me/totp:start)
	StartRegisterTOTP(w http.ResponseWriter, r *http.Request)
	// RedeemRecoveryCode 確認済みのメールアドレスとリカバリーコードで復旧を始める（4.12）
	// (POST /v1/recovery/code:redeem)
	RedeemRecoveryCode(w http.ResponseWriter, r *http.Request)
	// StartEmailRecovery 確認済みのメールによる復旧を始める（4.12）
	// (POST /v1/recovery/email:start)
	StartEmailRecovery(w http.ResponseWriter, r *http.Request)
	// VerifyEmailRecovery メールのコードかリンクのトークンで復旧専用のセッションを得る
	// (POST /v1/recovery/email:verify)
	VerifyEmailRecovery(w http.ResponseWriter, r *http.Request)
	// RedeemRecoveryLink 運営者が発行した復旧用リンクで復旧専用のセッションを得る
	// (POST /v1/recovery/link:redeem)
	RedeemRecoveryLink(w http.ResponseWriter, r *http.Request)
	// CompleteRecovery 復旧を終える
	// (POST /v1/recovery:complete)
	CompleteRecovery(w http.ResponseWriter, r *http.Request)
}

